#include <stdio.h>

void print_array(const int a[], int n) {
    for (int i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
}

void insertion_sort(int a[], int n) {
    for (int i = 1; i < n; i++) {
        int key = a[i];
        int j = i - 1;
        while (j >= 0 && a[j] > key) {
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = key;
        printf("Insert %d: ", key);
        print_array(a, n);
    }
}

int main(void) {
    int cards[] = {5, 2, 9, 1, 6, 3};
    int n = sizeof(cards) / sizeof(cards[0]);

    insertion_sort(cards, n);
    return 0;
}

